import React, { useEffect, useState, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import { milkService, animalService } from '../services/api';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import toast from 'react-hot-toast';
import { Plus, Calendar } from 'lucide-react';

export default function MilkPage() {
  const { user } = useAuth();
  const farmId = user?.farm_id;
  const [summary, setSummary] = useState(null);
  const [records, setRecords] = useState([]);
  const [animals, setAnimals] = useState([]);
  const [month, setMonth] = useState(new Date().toISOString().slice(0, 7));
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({
    animal_id: '', record_date: new Date().toISOString().split('T')[0],
    quantity: '', notes: ''
  });

  const load = useCallback(async () => {
    if (!farmId) return;
    setLoading(true);
    try {
      const [sumRes, listRes, animRes] = await Promise.allSettled([
        milkService.summary(farmId, month),
        milkService.list(farmId, { from: month + '-01' }),
        animalService.list(farmId, 1, 100, { status: 'active', gender: 'F' })
      ]);
      if (sumRes.status === 'fulfilled') setSummary(sumRes.value.data);
      if (listRes.status === 'fulfilled') setRecords(listRes.value.data.data || []);
      if (animRes.status === 'fulfilled') setAnimals(animRes.value.data.data || []);
    } catch {
      toast.error('Veri yüklenemedi');
    } finally {
      setLoading(false);
    }
  }, [farmId, month]);

  useEffect(() => {
    load();
  }, [load]);

  const handleAdd = async (e) => {
    e.preventDefault();
    if (!form.animal_id || !form.quantity) {
      toast.error('Hayvan ve miktar gerekli');
      return;
    }
    try {
      await milkService.create(farmId, form);
      toast.success('Süt kaydı eklendi');
      setShowForm(false);
      setForm({ animal_id: '', record_date: new Date().toISOString().split('T')[0], quantity: '', notes: '' });
      load();
    } catch {
      toast.error('İşlem başarısız');
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">🥛 Süt Üretimi</h1>
          <p className="text-sm text-gray-500">Günlük süt verimi ve trend takibi</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 bg-white px-3 py-1.5 rounded-xl border border-gray-200 text-sm">
            <Calendar className="w-4 h-4 text-gray-400" />
            <input
              type="month"
              value={month}
              onChange={e => setMonth(e.target.value)}
              className="border-none bg-transparent font-medium text-gray-700 text-sm focus:outline-none cursor-pointer"
            />
          </div>
          <button onClick={() => setShowForm(!showForm)} className={`btn-primary flex items-center justify-center gap-2 ${showForm ? 'bg-red-500 hover:bg-red-600' : ''}`}>
            {showForm ? 'İptal' : <><Plus className="w-4 h-4" /> Kayıt Ekle</>}
          </button>
        </div>
      </div>

      {/* Özet kartları */}
      {summary && (
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div className="card text-center group hover:border-blue-200 transition-colors">
            <p className="text-gray-400 text-xs font-bold uppercase tracking-wider">Aylık Toplam</p>
            <p className="text-3xl font-black text-blue-600 mt-2">{summary.grand_total || 0} L</p>
          </div>
          <div className="card text-center group hover:border-green-200 transition-colors">
            <p className="text-gray-400 text-xs font-bold uppercase tracking-wider">Günlük Ortalama</p>
            <p className="text-3xl font-black text-green-600 mt-2">{summary.avg_daily || 0} L</p>
          </div>
          <div className="card text-center group hover:border-orange-200 transition-colors">
            <p className="text-gray-400 text-xs font-bold uppercase tracking-wider">Hayvan Sayısı</p>
            <p className="text-3xl font-black text-orange-600 mt-2">{summary.by_animal?.length || 0}</p>
          </div>
        </div>
      )}

      {/* Form */}
      {showForm && (
        <div className="card border-blue-100 bg-blue-50/20 animate-in fade-in slide-in-from-top-4">
          <h2 className="text-lg font-bold mb-4 text-blue-900">Yeni Süt Kaydı</h2>
          <form onSubmit={handleAdd} className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Hayvan Seçin (Dişi)</label>
                <select
                  value={form.animal_id}
                  onChange={e => setForm({ ...form, animal_id: e.target.value })}
                  className="input-field"
                  required
                >
                  <option value="">Hayvan Seçin...</option>
                  {animals.map(a => (
                    <option key={a.id} value={a.id}>
                      {a.name} ({a.code}) - {a.species}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Kayıt Tarihi</label>
                <input
                  type="date"
                  value={form.record_date}
                  onChange={e => setForm({ ...form, record_date: e.target.value })}
                  className="input-field"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Miktar (Litre)</label>
                <input
                  type="number"
                  step="0.1"
                  placeholder="Örn: 15.5"
                  value={form.quantity}
                  onChange={e => setForm({ ...form, quantity: e.target.value })}
                  className="input-field"
                  required
                />
              </div>
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Notlar</label>
              <textarea
                placeholder="Örn: Sabah sağımı, düşük verim vb."
                value={form.notes}
                onChange={e => setForm({ ...form, notes: e.target.value })}
                className="input-field"
                rows={2}
              />
            </div>
            <div className="flex gap-3">
              <button type="button" onClick={() => setShowForm(false)} className="btn-secondary flex-1">Vazgeç</button>
              <button type="submit" className="btn-primary flex-1">Kaydı Kaydet</button>
            </div>
          </form>
        </div>
      )}

      {/* Grafik */}
      {summary?.daily && summary.daily.length > 0 && (
        <div className="card">
          <div className="flex items-center justify-between mb-6">
            <h3 className="font-bold text-gray-900">Günlük Üretim Trendi</h3>
            <div className="flex items-center gap-2 text-xs font-medium text-gray-500">
              <span className="w-3 h-3 bg-blue-500 rounded-full"></span>
              Üretim (Litre)
            </div>
          </div>
          <div className="h-[250px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={summary.daily}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                <XAxis 
                  dataKey="record_date" 
                  tick={{ fontSize: 10, fill: '#94a3b8' }} 
                  axisLine={false}
                  tickLine={false}
                  tickFormatter={d => d?.slice(5)} 
                />
                <YAxis 
                  tick={{ fontSize: 10, fill: '#94a3b8' }} 
                  axisLine={false}
                  tickLine={false}
                />
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                  formatter={(v) => [`${parseFloat(v).toFixed(1)} L`, 'Üretim']} 
                />
                <Line 
                  type="monotone" 
                  dataKey="total" 
                  stroke="#3b82f6" 
                  strokeWidth={3} 
                  dot={{ r: 4, fill: '#3b82f6', strokeWidth: 2, stroke: '#fff' }}
                  activeDot={{ r: 6, strokeWidth: 0 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {/* Son kayıtlar */}
      <div className="card p-0 overflow-hidden">
        <div className="p-4 border-b bg-gray-50/50">
          <h3 className="font-bold text-gray-900">Son Süt Kayıtları</h3>
        </div>
        <div className="overflow-x-auto">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
            </div>
          ) : records.length === 0 ? (
            <div className="text-center py-12 text-gray-400">
              <p className="text-4xl mb-2">🥛</p>
              <p className="font-medium text-sm">Henüz süt kaydı bulunmuyor</p>
            </div>
          ) : (
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Tarih</th>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Hayvan</th>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Notlar</th>
                  <th className="text-right px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Miktar</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {records.slice(0, 15).map(r => (
                  <tr key={r.id} className="hover:bg-blue-50/30 transition-colors">
                    <td className="px-6 py-4 whitespace-nowrap text-gray-600 font-medium">{r.record_date}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="bg-teal-50 text-teal-700 px-2 py-1 rounded-md font-bold text-xs border border-teal-100">
                        {r.animal?.name ? `${r.animal.name} (${r.animal.code})` : `#${r.animal_id}`}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-gray-500 italic max-w-xs truncate">{r.notes || '—'}</td>
                    <td className="px-6 py-4 text-right">
                      <span className="font-black text-blue-700">{r.quantity} L</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}
